    const dataset = loadDataset({ outputsPath, referencesPath });
    console.log('✓ Dataset loaded');

    const evaluations = runEvaluations({
      outputs: dataset.outputs,
      references: dataset.references
    });
    console.log('✓ Evaluations run');

    // Test 1: No thresholds
    const report1 = generateReport({
      evaluations,
      outputsPath,
      referencesPath
    });
    console.log('✓ Report without thresholds generated');
    if (report1.passed !== undefined) {
      throw new Error('Report should not have "passed" field without thresholds');
    }

    // Test 2: All thresholds pass
    const report2 = generateReport({
      evaluations,
      outputsPath,
      referencesPath,
      thresholds: { exact_match: 0.9, toxicity: 0.5 }
