    if (!report2.passed) {
      throw new Error('Report should have passed=true');
    }
    if (report2.thresholds.length !== 2) {
      throw new Error('Report should have 2 threshold results');
    }

    // Test 3: Some thresholds fail
    const report3 = generateReport({
      evaluations,
      outputsPath,
      referencesPath,
      thresholds: { exact_match: 0.99 }
    });
    console.log('✓ Report with failing threshold generated');
    if (report3.passed) {
      throw new Error('Report should have passed=false');
