    // Test 4: Metric with no score fails threshold
    const evaluations4 = [
      {
        id: 'exact_match',
        label: 'Exact Match',
        score: null,
        total: 0
      },
      {
        id: 'toxicity',
        label: 'Toxicity',
        score: 1,
        total: 3
      }
    ];
    const report4 = generateReport({
      evaluations: evaluations4,
      outputsPath,
      referencesPath,
      thresholds: { exact_match: 0.5 }
    });
    console.log('✓ Report with null-score threshold generated');
    if (report4.passed) {
      throw new Error('Report should have passed=false when metric score is null');
    }

    // Test 5: Verify threshold structure
    const thresholdResult = report2.thresholds[0];
    if (!('metric' in thresholdResult) || !('min' in thresholdResult) ||
        !('score' in thresholdResult) || !('passed' in thresholdResult)) {
      throw new Error('Threshold result missing required fields');
    }

    console.log('✓ All tests passed!');
  } finally {
    // Cleanup
    fs.rmSync(tmpDir, { recursive: true, force: true });
  }
}

runTests().catch(error => {
  console.error('✗ Test failed:', error.message);
  process.exit(1);
});

