// Test CLI threshold parsing
const testCases = [
  {
    input: 'exact_match=0.9',
    expected: { exact_match: 0.9 },
    shouldFail: false,
    name: 'Valid threshold'
  },
  {
    input: 'toxicity=0.95',
    expected: { toxicity: 0.95 },
    shouldFail: false,
    name: 'Valid toxicity threshold'
  },
  {
    input: 'length_variance=0.5',
    expected: { length_variance: 0.5 },
    shouldFail: false,
    name: 'Valid length variance threshold'
  },
  {
    input: 'exact_match',
    expected: null,
    shouldFail: true,
    name: 'Missing value'
  },
  {
    input: 'exact_match=',
    expected: null,
    shouldFail: true,
    name: 'Empty value'
  },
  {
    input: 'exact_match=1.5',
    expected: null,
    shouldFail: true,
    name: 'Value out of range (>1)'
  },
  {
    input: 'exact_match=-0.1',
    expected: null,
    shouldFail: true,
    name: 'Value out of range (<0)'
  },
  {
    input: 'unknown_metric=0.5',
    expected: null,
    shouldFail: true,
    name: 'Unknown metric'
  }
];

function parseThresholds(thresholdStrings) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return null;
  }

  const VALID_METRICS = ['exact_match', 'toxicity', 'length_variance'];
  const thresholds = {};

  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(`Invalid threshold format: '${thresholdStr}'. Expected format: metric=value`);
    }

    const [, metricId, valueStr] = match;
    const value = Number(valueStr);

    if (!VALID_METRICS.includes(metricId)) {
      throw new Error(`Unknown metric: '${metricId}'. Valid metrics: ${VALID_METRICS.join(', ')}`);
    }

    if (Number.isNaN(value) || value < 0 || value > 1) {
      throw new Error(`Invalid threshold value for '${metricId}': ${valueStr}. Must be a number between 0 and 1.`);
    }

    thresholds[metricId] = value;
  }

  return thresholds;
}

let passed = 0;
let failed = 0;

for (const testCase of testCases) {
  try {
    const result = parseThresholds([testCase.input]);
    if (testCase.shouldFail) {
      console.log(`✗ ${testCase.name}: Should have failed but didn't`);
      failed++;
    } else {
      if (JSON.stringify(result) === JSON.stringify(testCase.expected)) {
        console.log(`✓ ${testCase.name}`);
        passed++;
      } else {
