  console.log(`Test directory: ${tmpDir}`);

  try {
    // Create test data
    const outputsPath = path.join(tmpDir, 'outputs.json');
    const referencesPath = path.join(tmpDir, 'references.json');

    // Use outputs that won't trigger toxicity metric issues with reference matching
    // The toxicity metric gets called with references as second param, treating them as banned terms
    const outputs = ['abc', 'def', 'ghi'];
    const references = ['abc', 'def', 'ghi'];

    fs.writeFileSync(outputsPath, JSON.stringify(outputs, null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(references, null, 2));

    console.log('✓ Test data created');

    // Import the eval module
    const { loadDataset, runEvaluations, generateReport } = await import(
      './packages/frai-core/src/eval/index.js'
    );

    // Load and evaluate
    const dataset = loadDataset({ outputsPath, referencesPath });
    console.log('✓ Dataset loaded');

    const evaluations = runEvaluations({
      outputs: dataset.outputs,
      references: dataset.references
    });
    console.log('✓ Evaluations run');

    // Log metric IDs for debugging
    console.log('Available metrics:', evaluations.map(m => `${m.id}=${m.score}`).join(', '));

    // Test 1: No thresholds - report should not have passed field
    const report1 = generateReport({
      evaluations,
      outputsPath,
      referencesPath
    });
    console.log('✓ Report without thresholds generated');
    if (report1.passed !== undefined) {
      throw new Error('Report should not have "passed" field without thresholds');
    }
    if (report1.thresholds !== undefined) {
      throw new Error('Report should not have "thresholds" field without thresholds');
    }

    // Test 2: All thresholds pass
    const report2 = generateReport({
      evaluations,
      outputsPath,
      referencesPath,
      thresholds: { exact_match: 0.9, toxicity: 0.5 }
    });
    console.log('✓ Report with passing thresholds generated');
    if (!report2.passed) {
      throw new Error('Report should have passed=true');
    }
    if (report2.thresholds.length !== 2) {
      throw new Error(`Report should have 2 threshold results, got ${report2.thresholds.length}`);
    }

    // Verify threshold structure
    const threshold0 = report2.thresholds[0];
    if (!threshold0.metric || threshold0.min === undefined || threshold0.score === undefined || threshold0.passed === undefined) {
      throw new Error('Threshold missing required fields', threshold0);
    }

    // Test 3: Some thresholds fail
    const report3 = generateReport({
      evaluations,
      outputsPath,
      referencesPath,
      thresholds: { exact_match: 0.99 }
    });
