    const report1 = generateReport({
      evaluations,
      outputsPath,
      referencesPath
    });
    console.log('✓ Report without thresholds generated');
    if (report1.passed !== undefined) {
      throw new Error('Report should not have "passed" field without thresholds');
    }
    if (report1.thresholds !== undefined) {
      throw new Error('Report should not have "thresholds" field without thresholds');
    }

    // Test 2: All thresholds pass (use actual metric values)
    // Find the metric scores to create valid thresholds
    const exactMatchMetric = evaluations.find(m => m.id === 'exact_match');
    const toxicityMetric = evaluations.find(m => m.id === 'toxicity');
    const thresholds = {};
    if (exactMatchMetric && exactMatchMetric.score !== null) {
      thresholds.exact_match = exactMatchMetric.score - 0.1; // Set threshold below score
    }
    if (toxicityMetric && toxicityMetric.score !== null) {
      thresholds.toxicity = toxicityMetric.score - 0.1; // Set threshold below score
    }

    const report2 = generateReport({
      evaluations,
      outputsPath,
      referencesPath,
      thresholds
    });
    console.log('✓ Report with passing thresholds generated');
    if (!report2.passed) {
      throw new Error('Report should have passed=true');
    }
    if (Object.keys(thresholds).length > 0 && report2.thresholds.length !== Object.keys(thresholds).length) {
      throw new Error(`Report should have ${Object.keys(thresholds).length} threshold results, got ${report2.thresholds.length}`);
    }

    // Verify threshold structure
    const threshold0 = report2.thresholds[0];
    if (!threshold0.metric || threshold0.min === undefined || threshold0.score === undefined || threshold0.passed === undefined) {
      throw new Error('Threshold missing required fields', threshold0);
    }

    // Test 3: Some thresholds fail
    const report3 = generateReport({
      evaluations,
      outputsPath,
      referencesPath,
      thresholds: { exact_match: 0.99 }
    });
    console.log('✓ Report with failing threshold generated');
    if (report3.passed) {
      throw new Error('Report should have passed=false');
    }
    if (!report3.thresholds[0]) {
      throw new Error('Report should have threshold result');
    }
    if (report3.thresholds[0].passed !== false) {
      throw new Error('Failing threshold should have passed=false');
    }

    // Test 4: Metric with no score fails threshold
    const evaluations4 = [
      {
        id: 'exact_match',
        label: 'Exact Match',
        score: null,
        total: 0
      }
    ];
    const report4 = generateReport({
      evaluations: evaluations4,
      outputsPath,
      referencesPath,
      thresholds: { exact_match: 0.5 }
    });
    console.log('✓ Report with null-score threshold generated');
    if (report4.passed) {
      throw new Error('Report should have passed=false when metric score is null');
    }
    if (report4.thresholds[0].score !== null) {
      throw new Error('Null score should be preserved as null');
    }

    // Test 5: JSON serialization works
    const jsonStr = JSON.stringify(report2);
    const parsed = JSON.parse(jsonStr);
    if (!parsed.passed || !parsed.thresholds) {
      throw new Error('JSON roundtrip failed');
    }
    console.log('✓ JSON serialization works');

    // Test 6: Markdown report includes thresholds
    const { toMarkdown } = await import('./packages/frai-core/src/eval/reporters.js');
    const markdown = toMarkdown(report2);
    if (!markdown.includes('## Thresholds')) {
      throw new Error('Markdown report missing Thresholds section');
    }
    if (!markdown.includes('PASS') && !markdown.includes('FAIL')) {
      throw new Error('Markdown report missing PASS/FAIL status');
    }
    console.log('✓ Markdown report includes thresholds');

    // Test 7: Markdown report for failed thresholds
    const markdown3 = toMarkdown(report3);
    if (!markdown3.includes('FAIL')) {
      throw new Error('Markdown report missing FAIL status for failed threshold');
    }
    console.log('✓ Markdown report shows FAIL status');

    console.log('\n✓ All tests passed!');
  } finally {
    // Cleanup
    fs.rmSync(tmpDir, { recursive: true, force: true });
  }
}

runTests().catch(error => {
  console.error('✗ Test failed:', error.message);
  if (error.stack) console.error(error.stack);
  process.exit(1);
});

