import fs from 'fs';
import path from 'path';
import os from 'os';

async function testThresholdIntegration() {
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-threshold-integration-'));
  console.log(`Test directory: ${tmpDir}`);

  try {
    // Create test data with exact matches
    const outputsPath = path.join(tmpDir, 'outputs.json');
    const referencesPath = path.join(tmpDir, 'references.json');

    const outputs = ['output alpha', 'output beta', 'output gamma'];
    const references = ['Output Alpha', 'Output Beta', 'Output Gamma'];

    fs.writeFileSync(outputsPath, JSON.stringify(outputs, null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(references, null, 2));
    console.log('✓ Test data created');

    // Test 1: Core library - no thresholds
    {
      const { loadDataset, runEvaluations, generateReport } = await import(
        './packages/frai-core/src/eval/index.js'
      );

      const dataset = loadDataset({ outputsPath, referencesPath });
      const evaluations = runEvaluations({
        outputs: dataset.outputs,
        references: dataset.references
      });
      const report = generateReport({
        evaluations,
        outputsPath,
        referencesPath
      });

      if (report.passed !== undefined || report.thresholds !== undefined) {
        throw new Error('Report without thresholds should not have passed/thresholds fields');
      }
      console.log('✓ Core library: no thresholds - no passed/thresholds fields');
    }

    // Test 2: Core library - with passing thresholds
    {
      const { loadDataset, runEvaluations, generateReport } = await import(
        './packages/frai-core/src/eval/index.js'
      );

      const dataset = loadDataset({ outputsPath, referencesPath });
      const evaluations = runEvaluations({
        outputs: dataset.outputs,
        references: dataset.references
      });

      const exactMatchScore = evaluations.find(m => m.id === 'exact_match').score;

      const report = generateReport({
        evaluations,
        outputsPath,
        referencesPath,
        thresholds: { exact_match: exactMatchScore - 0.1 }
      });

      if (!report.passed) {
        throw new Error('Report should have passed=true');
      }
      if (report.thresholds.length !== 1) {
        throw new Error('Report should have 1 threshold');
      }
      if (!report.thresholds[0].passed) {
        throw new Error('Threshold should have passed=true');
      }
      console.log('✓ Core library: passing threshold - passed=true');
    }

    // Test 3: Core library - with failing threshold
    {
      const { loadDataset, runEvaluations, generateReport } = await import(
        './packages/frai-core/src/eval/index.js'
      );

      const dataset = loadDataset({ outputsPath, referencesPath });
      const evaluations = runEvaluations({
        outputs: dataset.outputs,
        references: dataset.references
      });

      const report = generateReport({
        evaluations,
        outputsPath,
        referencesPath,
        thresholds: { exact_match: 1.5 } // Impossible threshold
      });

      if (report.passed) {
        throw new Error('Report should have passed=false');
      }
      if (report.thresholds[0].passed) {
        throw new Error('Threshold should have passed=false');
      }
      console.log('✓ Core library: failing threshold - passed=false');
    }

    // Test 4: JSON report includes thresholds
    {
      const { loadDataset, runEvaluations, generateReport, writeReport } = await import(
        './packages/frai-core/src/eval/index.js'
      );

      const dataset = loadDataset({ outputsPath, referencesPath });
      const evaluations = runEvaluations({
        outputs: dataset.outputs,
        references: dataset.references
      });

      const report = generateReport({
        evaluations,
        outputsPath,
        referencesPath,
        thresholds: { exact_match: 0.5 }
      });

      const reportPath = path.join(tmpDir, 'report.json');
      writeReport({
        report,
        format: 'json',
        reportPath
      });

      const reportContent = JSON.parse(fs.readFileSync(reportPath, 'utf8'));
      if (!reportContent.passed || !reportContent.thresholds) {
        throw new Error('JSON report missing passed/thresholds');
      }
      console.log('✓ JSON report includes passed and thresholds');
    }

    // Test 5: Markdown report includes Thresholds section
    {
      const { loadDataset, runEvaluations, generateReport, writeReport } = await import(
        './packages/frai-core/src/eval/index.js'
      );

      const dataset = loadDataset({ outputsPath, referencesPath });
      const evaluations = runEvaluations({
        outputs: dataset.outputs,
        references: dataset.references
      });

      const report = generateReport({
        evaluations,
        outputsPath,
        referencesPath,
        thresholds: { exact_match: 0.5 }
      });

      const reportPath = path.join(tmpDir, 'report.md');
      writeReport({
        report,
        format: 'markdown',
        reportPath
      });

      const reportContent = fs.readFileSync(reportPath, 'utf8');
      if (!reportContent.includes('## Thresholds')) {
        throw new Error('Markdown report missing Thresholds section');
      }
      if (!reportContent.includes('PASS')) {
        throw new Error('Markdown report missing PASS status');
      }
      console.log('✓ Markdown report includes Thresholds section with status');
    }

    // Test 6: Validate metric list (for error messages)
    {
      const validMetrics = ['exact_match', 'toxicity', 'length_variance'];
      const { loadDataset, runEvaluations } = await import(
        './packages/frai-core/src/eval/index.js'
      );

      const dataset = loadDataset({ outputsPath, referencesPath });
      const evaluations = runEvaluations({
        outputs: dataset.outputs,
        references: dataset.references
      });

      const returnedMetrics = evaluations.map(m => m.id);
      for (const metric of validMetrics) {
        if (!returnedMetrics.includes(metric)) {
          throw new Error(`Missing metric: ${metric}`);
        }
      }
      console.log('✓ All valid metrics returned by evaluations');
    }

    console.log('\n✓ All integration tests passed!');
  } finally {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  }
}

testThresholdIntegration().catch(error => {
  console.error('✗ Test failed:', error.message);
  process.exit(1);
});

